```typescript
/**
 * 二分查找：在已排序（升序）的数组中查找 target。
 * @returns target 的索引；不存在时返回 -1
 */
function binarySearch(nums: number[], target: number): number {
  let left = 0;
  let right = nums.length - 1;

  while (left <= right) {
    // 避免 (left + right) 溢出的写法，等价于 Math.floor((left + right) / 2)
    const mid = left + ((right - left) >> 1);
    const value = nums[mid];

    if (value === target) {
      return mid;
    }
    if (value < target) {
      left = mid + 1; // target 在右半区
    } else {
      right = mid - 1; // target 在左半区
    }
  }

  return -1;
}
```

使用示例：

```typescript
binarySearch([1, 3, 5, 7, 9], 5); // 2
binarySearch([1, 3, 5, 7, 9], 4); // -1
binarySearch([], 1);              // -1
```

两点说明：

- **数组有重复元素时**，上面的实现返回其中任意一个匹配位置（不保证是第一个）。如果需要**第一个**匹配项，把命中分支改为 `right = mid - 1` 并另存结果；需要**最后一个**则改为 `left = mid + 1`。
- 复杂度为 O(log n)，空间 O(1)。

